insert into public.members (id, code, role, status, nome, email, cadeira, cidade, titulacao, instagram, bio, full_history, foto, palestras, data_registro) values ('policarpo', '#001001', 'diretor', 'ativo', 'José Policarpo Miranda Junior', 'Dr.PolicarpoEngenheiro@outlook.pt', 'Patrono 01 — Presidente', 'Macapá, AP', 'Engenheiro Florestal, Doutor em Biotecnologia e Biodiversidade', 'https://www.instagram.com/policarpo.junior.311', 'Escritor, pintor, fotógrafo e pesquisador. Presidente da Academia de Letras Barão do Rio Branco.', 'Com atuação multifacetada, pesquisador, professor, gestor público, escritor e acadêmico, José Policarpo Miranda Junior construiu uma carreira marcada pelo comprometimento com a defesa ambiental, com a ciência e com a cultura. Nascido em Belém do Pará, é Engenheiro Florestal, Doutor em Biotecnologia e Biodiversidade pela Universidade Federal do Amapá – UNIFAP. Presidente da Academia de Letras Barão do Rio Branco. Sua obra, tanto científica quanto literária, contribui para o fortalecimento do pensamento amazônida e para a divulgação de saberes que valorizam a biodiversidade, a educação, a história e a identidade regional.', '/imagens/policarpo-novo.jpg', true, '2025-01-26T10:00:00.000Z');
insert into public.members (id, code, role, status, nome, email, cadeira, cidade, titulacao, instagram, bio, full_history, foto, palestras, data_registro) values ('elaine-araujo', '#001002', 'associado', 'ativo', 'Elaine Araújo', 'elaine.a3@icloud.com', 'Cadeira Castro Alves', 'Santana, AP', 'Mestranda em Letras, Especialista em Docência Superior, Pedagoga', 'https://www.instagram.com/elainearaujoferreira_tv', 'Professora Mestranda em Letras, compositora, poetisa e produtora cultural do Amapá.', 'Professora Mestranda do curso de Letras, Literatura e Críticas Literárias da PUC-Goiás, Especialista em Docência do Ensino Superior pela Faculdade CETE. Graduada em Licenciatura em Pedagogia pelo IFPA e em Teologia pela FATECH. Presidente da Fundação de Cultura de Santana-Amapá de 2022 a 2023. Autora dos Hinos Municipais de Santana (1989) e Laranjal do Jari (1995) e do livro ''Dicionário Caboquês''.', '/imagens/elaine-araujo.jpg', true, '2025-01-26T10:00:00.000Z');
insert into public.members (id, code, role, status, nome, email, cadeira, cidade, titulacao, instagram, bio, full_history, foto, palestras, data_registro) values ('jacqueline-pharlan', '#001003', 'associado', 'ativo', 'Jacqueline Pharlan de Camargo', 'jakepharlan@hotmail.com', 'Patrono Ivo Cannuty — Cadeira 052', 'Macapá, AP', 'Mestre em Educação, Engenheira de Segurança do Trabalho', 'https://www.instagram.com/jacquepharlan', 'Professora de inglês, Engenheira de Segurança do Trabalho, escritora e cicloativista com obras publicadas nacional e internacionalmente.', 'Jacqueline Pharlan de Camargo é professora de inglês, Engenheira de Segurança do Trabalho, escritora e cicloativista. Mestre em Educação com ênfase em gestão educacional e em Tecnologias Emergentes. Livros publicados sobre Cicloturismo, poesias e contos em coletâneas. Participou de feiras culturais como o Equinócio das Águas e Feira Internacional do Livro de Caiena.', '/imagens/jacqueline-pharlan.jpg', true, '2025-01-26T10:00:00.000Z');
insert into public.members (id, code, role, status, nome, email, cadeira, cidade, titulacao, instagram, bio, full_history, foto, palestras, data_registro) values ('maria-lucia-coelho', '#001004', 'associado', 'ativo', 'Maria Lúcia Coelho', 'luciacoelhoadv@uol.com.br', 'Patrono Maria Beatriz do Nascimento — Cadeira 51', 'Macapá, AP', 'Advogada, Mestra em Comunicação, Doutoranda em Educação', '', 'Escritora, poetisa, advogada, mestra em Comunicação e doutoranda em Educação.', 'Nascida em Afuá, Estado do Pará. Mestra em Comunicação, Linguagens e Cultura e Doutoranda em Educação. Assistente Social, Advogada. Autora do livro de poesias ''Sinfonia de Emoções'', além de obras nas categorias crônicas e contos.', '/imagens/maria-lucia-coelho.jpg', true, '2026-04-22T14:12:00.000Z');
insert into public.members (id, code, role, status, nome, email, cadeira, cidade, titulacao, instagram, bio, full_history, foto, palestras, data_registro) values ('mathias-alencar', '#001005', 'associado', 'ativo', 'Cesar Augusto Mathias de Alencar', 'escoladeescrita@gmail.com', 'Patrono João Cabral de Melo Neto — Cadeira 50', 'Macapá, AP', 'Doutor em Filosofia (UFRJ), Professor Efetivo UNIFAP e UFPA', 'https://www.instagram.com/mathiasdealencar', 'Poeta e professor de Filosofia. Doutor pela UFRJ, autor de três livros de poesia e do romance Bárbara.', 'Mathias de Alencar é poeta e professor. Doutor em Filosofia pela UFRJ, é docente efetivo de Filosofia na UNIFAP e pós-graduação da UFPA. Autor de ''Ninguém há de doar-se a dois amores ou Julieta'' (2023), ''Poem(a)limpo'' e ''Bárbara''.', '/imagens/mathias-alencar.jpg', true, '2026-04-26T11:34:00.000Z');
