insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b1', 'policarpo', 'O Forte', 'A defesa de um império', 'Uma imersão na cultura e na força dos defensores do nosso território. Obra de maturidade poética e política ambientada na Amazônia profunda.', '/images/capa-forte.png', 'Romance', 'Adulto (18+)', '2024-01-01', 49.9, '[{"plataforma":"amazon","url":"https://amazon.com.br"},{"plataforma":"mercado","url":"https://mercadolivre.com.br"}]'::jsonb, array['amazônia', 'história', 'épico']::text[], 'publicado', '2024-01-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b2', 'policarpo', 'Samurai de Carvão', 'A honra nas chamas escurecidas', 'Um mergulho denso no mundo distópico, onde a honra molda as espadas no limite da realidade moderna.', '/images/capa-samurai.png', 'Ficção Científica', 'Adulto (18+)', '2023-08-01', 69.9, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['ficção', 'honra', 'distopia']::text[], 'publicado', '2023-08-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b3', 'policarpo', 'A Vila', 'Histórias do extremo Norte', 'Os mitos e vivências amazônicas recontados pela vivência intrínseca com os ribeirinhos e povos originários.', '/images/capa-vila.png', 'Conto', 'Adulto (18+)', '2023-11-01', 39.9, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['amazônia', 'contos', 'ribeirinhos']::text[], 'publicado', '2023-11-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b4', 'policarpo', 'Pensamentos na Escuridão', 'A traição do destino', 'Um convite poético a entender os labirintos do ciúme, da dúvida e da memória abstrata.', '/images/capa-pensamentos.png', 'Poesia', 'Adulto (18+)', '2023-06-01', 35, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['poesia', 'filosofia', 'introspecção']::text[], 'publicado', '2023-06-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b5', 'policarpo', 'Passos Perdidos', 'Onde terminam os caminhos', 'Uma obra investigativa e literária recheada de ação e reflexões sobre a história amapaense.', '/images/capa-passos.png', 'Crônica', 'Adulto (18+)', '2024-02-01', 45, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['crônica', 'amapá', 'investigação']::text[], 'publicado', '2024-02-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b6', 'policarpo', 'Caipira', 'A caminhada eterna', 'A aridez da terra e a magia do interior do Brasil retratadas em prosa poética envolvente.', '/images/capa-caipira.png', 'Romance', 'Adulto (18+)', '2024-05-01', 59.9, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['cultura', 'brasil', 'romance']::text[], 'publicado', '2024-05-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b7', 'policarpo', 'Turminha', 'O futuro nas entrelinhas', 'A perspectiva encantadora das crianças e do aprendizado lúdico na primeira idade.', '/images/capa-turminha.png', 'Literatura Infantil', 'Infantil (0–8 anos)', '2024-09-01', 29.9, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['infantil', 'educação', 'leitura']::text[], 'publicado', '2024-09-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b8', 'elaine-araujo', 'Dicionário Caboquês', 'A Língua do Cabuçu nas Brenhas da Amazônia', 'Entre saberes e fazeres, um resgate etnolinguístico das expressões caboclas e tradições orais do Amapá e do Norte.', '/imagens/elaine-araujo.jpg', 'Acadêmico', 'Todas as idades', '2025-03-01', 49.9, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['caboquês', 'amazônia', 'linguística', 'cultura']::text[], 'publicado', '2025-03-01T00:00:00.000Z');
insert into public.books (id, member_id, titulo, subtitulo, sinopse, capa_url, genero, faixa_etaria, data_publicacao, preco, links_venda, tags, status, created_at) values ('b9', 'mathias-alencar', 'Bárbara', 'Edição Especial 10 Anos', 'Romance aclamado pela crítica literária. Uma narrativa sensorial que explora as imagens e sons das palavras como potências estéticas.', '/imagens/mathias-alencar.jpg', 'Romance', 'Adulto (18+)', '2025-06-01', 54.9, '[{"plataforma":"amazon","url":"https://amazon.com.br"}]'::jsonb, array['romance', 'filosofia', 'literatura']::text[], 'publicado', '2025-06-01T00:00:00.000Z');
insert into public.musics (id, member_id, titulo, descricao, capa_url, tipo, plataforma, link_externo, tags, status, created_at) values ('m1', 'elaine-araujo', 'Hino de Santana e Vozes da Floresta', 'Composições e hinos oficiais celebrando a história e a biodiversidade amazônica.', '/imagens/elaine-araujo.jpg', 'Música Autoral', 'spotify', 'https://open.spotify.com', array['amazônia', 'hinos', 'santana']::text[], 'publicado', '2025-01-01T00:00:00.000Z');
insert into public.musics (id, member_id, titulo, descricao, capa_url, tipo, plataforma, link_externo, tags, status, created_at) values ('m2', 'mathias-alencar', 'Bárbara — Audiolivro & Poesias Faladas', 'Versão falada com declamações poéticas e trilha incidental acústica.', '/imagens/mathias-alencar.jpg', 'Audiolivro', 'youtube', 'https://youtube.com', array['audiolivro', 'poesia', 'teatral']::text[], 'publicado', '2025-06-01T00:00:00.000Z');
insert into public.musics (id, member_id, titulo, descricao, capa_url, tipo, plataforma, link_externo, tags, status, created_at) values ('m3', 'policarpo', 'Contos e Memórias do Amapá', 'Gravação especial de contos narrados pelo Presidente da Academia.', '/imagens/policarpo-novo.jpg', 'Podcast Literário', 'spotify', 'https://open.spotify.com', array['história', 'amapá', 'podcast']::text[], 'publicado', '2025-02-01T00:00:00.000Z');
